import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.CWgsre3x.js";const h=JSON.parse('{"title":"API keys & secure setup","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/api-keys.md","filePath":"integrations/api-keys.md"}'),o={name:"integrations/api-keys.md"};function s(n,e,d,c,p,l){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="api-keys-secure-setup" tabindex="-1">API keys &amp; secure setup <a class="header-anchor" href="#api-keys-secure-setup" aria-label="Permalink to &quot;API keys &amp; secure setup&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Source-reviewed v0.7.26. This is an administrator guide, not confirmation of a live provider connection. Installation-specific credentials are never published.</p></div><h2 id="who-configures-what" tabindex="-1">Who configures what? <a class="header-anchor" href="#who-configures-what" aria-label="Permalink to &quot;Who configures what?&quot;">​</a></h2><p>Company administrators review integration readiness and permissions. An authorized hosting/platform administrator provisions server secrets. The integration catalog and payment readiness panel do not provide a general-purpose secret vault or browser credential entry.</p><p>TransferBook+ operator API authentication uses RS256 bearer tokens plus the selected <code>X-Company-Id</code>; the server checks tenant membership and role. A provider API key cannot authenticate an operator. See <a href="/developers/authentication.html">Authentication</a>.</p><h2 id="setup-procedure" tabindex="-1">Setup procedure <a class="header-anchor" href="#setup-procedure" aria-label="Permalink to &quot;Setup procedure&quot;">​</a></h2><ol><li>Confirm the installed release, company, approved capability and sandbox account. Obtain credentials from the provider&#39;s official developer console; use separate test and production credentials.</li><li>Confirm the exact runtime variable names in the installed release. Example names in these guides are configuration identifiers, not secret values.</li><li>Put server credentials in a restricted deployment environment or supported secret store, accessible only to the authorized service. Preserve existing configuration and permissions during updates. Never store them in Git, public website settings, browser storage, screenshots or support transcripts.</li><li>Only browser-intended public configuration may use <code>VITE_</code> variables; those values are embedded at build time. The Maps browser key must have website and API restrictions. Never put private credentials, JWT signing keys or database passwords there.</li><li>Apply only the approved provider-specific build or service configuration through the guarded installation process. Do not enable public intake as a side effect. Validate tenant scope, permissions, failure behavior, quotas and audit records in sandbox with synthetic data.</li><li>Obtain owner approval before live activation. Record the provider, environment, key identifier (not value), scopes, responsible administrator, rotation date and acceptance result.</li></ol><h2 id="rotation-and-troubleshooting" tabindex="-1">Rotation and troubleshooting <a class="header-anchor" href="#rotation-and-troubleshooting" aria-label="Permalink to &quot;Rotation and troubleshooting&quot;">​</a></h2><p>Disable the affected capability before replacing compromised credentials. Revoke at the provider, provision replacements in the approved environment, retest and re-enable only after authorization. Do not expose credentials in diagnostic output. A 401/403 may indicate permissions, key restrictions or wrong environment; a 429 indicates a quota or rate limit. Do not bypass these controls. A successful health endpoint does not establish external provider delivery.</p><p>Use <a href="/integrations/third-party-api-setup.html">Third-party API setup</a> and <a href="/security-privacy/">Security &amp; Privacy</a> for additional requirements.</p>',10)])])}const m=t(o,[["render",s]]);export{h as __pageData,m as default};
